"""Compare the OpenAPI document generated by the app with the frozen contract (docs/api/openapi.yaml), task B-28.

Both documents are reduced to a canonical form first, so that only differences of meaning are reported, not
differences of spelling: `$ref` is resolved, `allOf` merged, `type: [x, null]` and `anyOf: [x, null]` both become
"x, nullable", and titles, descriptions, examples and `x-` extensions are ignored.
"""
from __future__ import annotations

from typing import Any

HTTP_METHODS = ("get", "put", "post", "patch", "delete")
# Responses every protected or validated route may add without the contract listing them (global conventions of the
# contract header: bearer authentication, validation errors, rate limiting).
IMPLICIT_STATUSES = {"401", "422", "429"}
IGNORED = {"title", "description", "summary", "example", "examples", "default", "deprecated", "readOnly",
           "writeOnly", "externalDocs", "xml", "discriminator"}
KEEP = ("format", "enum", "const", "minimum", "maximum", "exclusiveMinimum", "exclusiveMaximum", "minLength",
        "maxLength", "minItems", "maxItems", "minProperties", "pattern", "multipleOf")


def deref(doc: dict, node: Any) -> Any:
    seen = 0
    while isinstance(node, dict) and "$ref" in node:
        target = doc
        for part in node["$ref"].lstrip("#/").split("/"):
            target = target[part]
        node, seen = target, seen + 1
        if seen > 20:
            raise RecursionError(node)
    return node


def _merge_all_of(doc: dict, schema: dict) -> dict:
    merged: dict[str, Any] = {k: v for k, v in schema.items() if k != "allOf"}
    props: dict[str, Any] = dict(merged.get("properties", {}))
    required = set(merged.get("required", []))
    for part in schema["allOf"]:
        part = deref(doc, part)
        if "allOf" in part:
            part = _merge_all_of(doc, part)
        props.update(part.get("properties", {}))
        required |= set(part.get("required", []))
        for key, value in part.items():
            if key not in ("properties", "required", "allOf", "type"):
                merged.setdefault(key, value)
        merged.setdefault("type", part.get("type"))
    merged["properties"], merged["required"] = props, sorted(required)
    return merged


def canon(doc: dict, schema: Any) -> dict:
    """Canonical form of a schema, as a plain dict."""
    schema = deref(doc, schema)
    if schema is True or schema == {}:
        return {}
    if "allOf" in schema:
        schema = _merge_all_of(doc, schema)
    nullable = False
    for key in ("anyOf", "oneOf"):
        if key in schema:
            branches = [deref(doc, b) for b in schema[key]]
            real = [b for b in branches if b.get("type") != "null"]
            nullable = len(real) != len(branches)
            rest = {k: v for k, v in schema.items() if k != key}
            if len(real) == 1:
                inner = canon(doc, {**real[0], **{k: v for k, v in rest.items() if k not in real[0]}})
                return {**inner, **({"nullable": True} if nullable else {})}
            out = {"oneOf": sorted((canon(doc, b) for b in real), key=repr)}
            return {**out, **({"nullable": True} if nullable else {})}
    out: dict[str, Any] = {}
    kind = schema.get("type")
    if isinstance(kind, list):
        nullable = "null" in kind
        kind = [k for k in kind if k != "null"]
        kind = kind[0] if len(kind) == 1 else sorted(kind)
    if kind is None and "const" in schema:
        kind = {str: "string", int: "integer", bool: "boolean"}.get(type(schema["const"]))
    if kind is None and "properties" in schema:
        kind = "object"
    if kind:
        out["type"] = kind
    for key in KEEP:
        if key in schema and key != "const":
            out[key] = sorted(schema[key], key=repr) if key == "enum" else schema[key]
    if "const" in schema:  # a constant is a one-value enum
        out["enum"] = [schema["const"]]
    if "enum" in out and None in out["enum"]:  # an enum that lists null is nullable
        nullable = True
        out["enum"] = [v for v in out["enum"] if v is not None]
    if "items" in schema:
        out["items"] = canon(doc, schema["items"])
    if "properties" in schema:
        out["properties"] = {k: canon(doc, v) for k, v in sorted(schema["properties"].items())}
        out["required"] = sorted(schema.get("required", []))
    elif schema.get("required"):
        out["required"] = sorted(schema["required"])
    extra = schema.get("additionalProperties")
    if extra is False:
        out["additionalProperties"] = False
    elif isinstance(extra, dict) and extra:
        out["additionalProperties"] = canon(doc, extra)
    if nullable:
        out["nullable"] = True
    return out


def diff_schema(expected: Any, actual: Any, where: str) -> list[str]:
    """Human readable differences between two canonical schemas."""
    if isinstance(expected, dict) and isinstance(actual, dict):
        out: list[str] = []
        for key in sorted(set(expected) | set(actual)):
            here = f"{where}.{key}" if where else key
            if key not in expected:
                out.append(f"{here}: not in the contract (code has {_short(actual[key])})")
            elif key not in actual:
                out.append(f"{here}: missing in the code (contract has {_short(expected[key])})")
            elif key in ("properties", "items") or isinstance(expected[key], dict):
                out += diff_schema(expected[key], actual[key], here)
            elif expected[key] != actual[key]:
                out.append(f"{here}: contract {_short(expected[key])} != code {_short(actual[key])}")
        return out
    return [] if expected == actual else [f"{where}: contract {_short(expected)} != code {_short(actual)}"]


def _short(value: Any) -> str:
    text = repr(value)
    return text if len(text) < 120 else text[:117] + "..."


# ------------------------------------------------------------------ operations

def operations(doc: dict) -> dict[tuple[str, str], dict]:
    """{(METHOD, path): operation} with the path-level parameters folded into each operation."""
    out = {}
    for path, item in doc["paths"].items():
        for method in HTTP_METHODS:
            if method in item:
                op = dict(item[method])
                op["parameters"] = [*item.get("parameters", []), *op.get("parameters", [])]
                out[(method.upper(), path)] = op
    return out


def _params(doc: dict, op: dict) -> dict[tuple[str, str], dict]:
    out = {}
    for raw in op.get("parameters", []):
        p = deref(doc, raw)
        schema = canon(doc, p.get("schema", {}))
        schema.pop("nullable", None)  # a query parameter cannot be null: an optional parameter is just absent
        default = deref(doc, p.get("schema", {})).get("default")
        out[(p["name"], p["in"])] = {"required": bool(p.get("required", False)), "schema": schema,
                                     "default": default}
    return out


def _is_public(doc: dict, op: dict) -> bool:
    security = op.get("security", doc.get("security"))
    return not security


def _json_schema(doc: dict, content: dict | None) -> dict | None:
    if not content:
        return None
    for media in ("application/json", "application/pdf", "text/csv", "multipart/form-data"):
        if media in content:
            return {"media": media, "schema": canon(doc, content[media].get("schema", {}))}
    return None


def diff_operation(contract: dict, generated: dict, spec_op: dict, gen_op: dict) -> list[str]:
    problems: list[str] = []
    if spec_op.get("operationId") != gen_op.get("operationId"):
        problems.append(f"operationId: contract {spec_op.get('operationId')!r} != code {gen_op.get('operationId')!r}")
    if spec_op.get("tags", [None])[:1] != gen_op.get("tags", [None])[:1]:
        problems.append(f"tag: contract {spec_op.get('tags')} != code {gen_op.get('tags')}")
    if _is_public(contract, spec_op) != _is_public(generated, gen_op):
        problems.append("authentication: " + ("the contract says public, the code requires a token"
                                              if _is_public(contract, spec_op) else
                                              "the contract requires a token, the code is public"))

    spec_params, gen_params = _params(contract, spec_op), _params(generated, gen_op)
    for key in sorted(set(spec_params) | set(gen_params)):
        name = f"parameter {key[1]} {key[0]!r}"
        if key not in gen_params:
            problems.append(f"{name}: missing in the code")
        elif key not in spec_params:
            problems.append(f"{name}: not in the contract")
        else:
            a, b = spec_params[key], gen_params[key]
            if a["required"] != b["required"]:
                problems.append(f"{name}: required is {a['required']} in the contract, {b['required']} in the code")
            if a["default"] != b["default"]:
                problems.append(f"{name}: default {a['default']!r} in the contract, {b['default']!r} in the code")
            problems += [f"{name} {d}" for d in diff_schema(a["schema"], b["schema"], "schema")]

    spec_body = deref(contract, spec_op.get("requestBody", {}))
    gen_body = deref(generated, gen_op.get("requestBody", {}))
    if bool(spec_body) != bool(gen_body):
        problems.append("requestBody: " + ("missing in the code" if spec_body else "not in the contract"))
    elif spec_body:
        if bool(spec_body.get("required", False)) != bool(gen_body.get("required", False)):
            problems.append(f"requestBody: required is {spec_body.get('required', False)} in the contract, "
                            f"{gen_body.get('required', False)} in the code")
        a, b = _json_schema(contract, spec_body.get("content")), _json_schema(generated, gen_body.get("content"))
        if a and b:
            problems += [f"requestBody {d}" for d in diff_schema(a, b, "")]

    spec_resp, gen_resp = spec_op.get("responses", {}), gen_op.get("responses", {})
    for code in sorted(set(spec_resp) | set(gen_resp)):
        if code not in gen_resp:
            problems.append(f"response {code}: declared by the contract, never produced by the code")
        elif code not in spec_resp:
            if code not in IMPLICIT_STATUSES:
                problems.append(f"response {code}: produced by the code, not declared by the contract")
        else:
            a = _json_schema(contract, deref(contract, spec_resp[code]).get("content"))
            b = _json_schema(generated, deref(generated, gen_resp[code]).get("content"))
            if bool(a) != bool(b):
                problems.append(f"response {code}: body {'missing in the code' if a else 'not in the contract'}")
            elif a:
                problems += [f"response {code} {d}" for d in diff_schema(a, b, "")]
    return problems


def compare(contract: dict, generated: dict,
            base: str = "/api/v1") -> tuple[dict[str, list[str]], list[str], list[str]]:
    """(differences per implemented operation, operations only in the code, operations only in the contract)."""
    spec_ops = operations(contract)
    gen_ops = {(m, p.removeprefix(base)): op for (m, p), op in operations(generated).items()}
    differences = {}
    for key in sorted(set(spec_ops) & set(gen_ops)):
        problems = diff_operation(contract, generated, spec_ops[key], gen_ops[key])
        if problems:
            differences[f"{key[0]} {key[1]}"] = problems
    only_code = sorted(f"{m} {p}" for m, p in set(gen_ops) - set(spec_ops))
    only_contract = sorted(spec_ops[k]["operationId"] for k in set(spec_ops) - set(gen_ops))
    return differences, only_code, only_contract
